def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in points:
        # A five-cell banner sits above the marker, with a framed marker below it.
        for x in range(max(0, c - 2), min(w, c + 3)):
            if 0 <= r - 2 < h:
                out[r - 2][x] = 5
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in (c - 2, c + 2):
                if 0 <= x < w:
                    out[y][x] = 2
        if 0 <= r + 2 < h:
            out[r + 2] = [2] * w
            for x in range(max(0, c - 2), min(w, c + 3)):
                out[r + 2][x] = 8
    return out
